import json, os
from collections import Counter
from html.parser import HTMLParser
from pathlib import Path
class Page(HTMLParser):
    def __init__(self, html):
        super().__init__(); self.tags=[]; self.feed(html)
    def handle_starttag(self, tag, attrs):
        self.tags.append((tag, dict(attrs)))
snapshots=json.loads((Path(os.environ['TEMP'])/'yolowisata-label-snapshots.json').read_text(encoding='utf-8'))
refs=set(); checked=0; groups=0
for snapshot in snapshots:
    tags=Page(snapshot['html']).tags
    counts=Counter(a['id'] for _,a in tags if 'id' in a)
    assert not [i for i,n in counts.items() if n>1], (snapshot['name'], 'duplicate IDs', counts)
    ids={a['id']:(tag,a) for tag,a in tags if 'id' in a}
